param([string]$RepoRoot=".",[string]$MetaEditorPath="",[string]$TerminalDataPath="")
$ErrorActionPreference="Stop";$root=(Resolve-Path $RepoRoot).Path
if(-not $MetaEditorPath){$MetaEditorPath=@("$env:ProgramFiles\MetaTrader 5\metaeditor64.exe","$env:ProgramFiles\MetaTrader 5\MetaEditor64.exe","$env:ProgramFiles(x86)\MetaTrader 5\metaeditor64.exe")|Where-Object{Test-Path $_}|Select-Object -First 1}
if(-not $MetaEditorPath -or -not(Test-Path $MetaEditorPath)){throw "MetaEditor64 not found. Pass -MetaEditorPath."};if(-not $TerminalDataPath){throw "Pass -TerminalDataPath."}
$inc=Join-Path $root "mql5\Include\AlphaLab\StrategyFactory\ClassicalAlgorithms";$dst=Join-Path $TerminalDataPath "MQL5\Include\AlphaLab\StrategyFactory\ClassicalAlgorithms";New-Item -ItemType Directory -Force -Path $dst|Out-Null;Copy-Item "$inc\*" $dst -Recurse -Force
$targets=@("mql5\Experts\StrategyFactory\UCE_I08_ClassicalAlgorithmsDiagnostic.mq5","mql5\Experts\StrategyFactoryTests\UCE_I08_ClassicalAlgorithmsSelfTest.mq5","mql5\Experts\StrategyFactoryTests\UCE_I08_CatalogParitySelfTest.mq5")
foreach($rel in $targets){$src=Join-Path $root $rel;$leaf=Split-Path $rel -Leaf;$cat=if($rel -like "*StrategyFactoryTests*"){"StrategyFactoryTests"}else{"StrategyFactory"};$dir=Join-Path $TerminalDataPath "MQL5\Experts\$cat";New-Item -ItemType Directory -Force -Path $dir|Out-Null;$target=Join-Path $dir $leaf;Copy-Item $src $target -Force;$log=$target+".compile.log";& $MetaEditorPath "/compile:$target" "/log:$log";if($LASTEXITCODE -ne 0 -or (Get-Content $log -Raw)-notmatch "0 errors, 0 warnings"){throw "Compilation not clean for $leaf. See $log"};Write-Host "PASS $leaf"}
